def pa_answer_by_id(rows,qid):
    for row in rows:
        if isinstance(row,dict) and row.get('id')==qid:
            return row
    return None

def pa_evidence_ids(answer):
    out=[]
    if not isinstance(answer,dict):
        return out
    evidence=answer.get('evidence',[])
    if isinstance(evidence,dict):
        evidence=[evidence]
    for item in evidence:
        if isinstance(item,dict):
            uid=item.get('unit_id')
            if uid not in out:
                out.append(uid)
    return out

def pa_clusters(spans,evidence_ids):
    positions={}
    i=0
    while i<len(spans):
        positions[spans[i].get('id')]=i
        i+=1
    selected=[]
    for uid in evidence_ids:
        if uid in positions:
            selected.append(positions[uid])
    selected=sorted(set(selected))
    groups=[]
    for pos in selected:
        if not groups or pos-groups[len(groups)-1][len(groups[len(groups)-1])-1]>2:
            groups.append([pos])
        else:
            groups[len(groups)-1].append(pos)
    out=[]
    for group in groups:
        start=max(0,group[0]-1)
        end=min(len(spans)-1,group[len(group)-1]+1)
        ids=[]
        j=start
        while j<=end:
            ids.append(spans[j].get('id'))
            j+=1
        out.append(ids)
    return out

def pa_add_fine_queries(queries,rows,clusters,prefix,operations):
    for ids in clusters:
        if not ids:
            continue
        suffix=str(ids[0])+'_'+str(ids[len(ids)-1])
        for operation in operations:
            qid=prefix+'_'+operation+'__'+suffix
            if pa_answer_by_id(rows,qid) is None:
                queries.append({'id':qid,'operation':operation,'unit_ids':ids})

def apply(inputs,premises):
    spans=[]
    for span in inputs.get('source_spans',[]):
        if isinstance(span,dict):
            spans.append(span)
    all_ids=[]
    for span in spans:
        all_ids.append(span.get('id'))
    if not all_ids:
        return {'queries':[]}
    rows=pa_rows(inputs.get('semantic_answers',[]))
    queries=[]
    disclosure_id='positive_disclosure_locator_v1'
    disposal_id='positive_disposal_locator_v1'
    disclosure=pa_answer_by_id(rows,disclosure_id)
    disposal=pa_answer_by_id(rows,disposal_id)
    if disclosure is None:
        queries.append({'id':disclosure_id,'operation':'positive_disclosure_norm_locator_v1','unit_ids':all_ids})
    elif disclosure.get('choice')=='candidate_found':
        clusters=pa_clusters(spans,pa_evidence_ids(disclosure))
        pa_add_fine_queries(queries,rows,clusters,'disclosure',['disclosure_norm_effect_v1','disclosure_owner_scope_v1','need_to_know_requirement_v1','confidentiality_safeguard_v1','extent_necessity_requirement_v1'])
    if disposal is None:
        queries.append({'id':disposal_id,'operation':'positive_disposal_norm_locator_v1','unit_ids':all_ids})
    elif disposal.get('choice')=='candidate_found':
        clusters=pa_clusters(spans,pa_evidence_ids(disposal))
        pa_add_fine_queries(queries,rows,clusters,'disposal',['disposal_action_profile_v1','disposal_trigger_profile_v1','disposal_material_scope_v1','post_disposal_retention_effect_v1'])
    return {'queries':queries}
